/** Float32 FIFO used to reframe 128-sample render quanta into model frames. */
class SampleFifo {
  constructor(capacity) {
    this.buffer = new Float32Array(capacity);
    this.readIndex = 0;
    this.writeIndex = 0;
    this.length = 0;
  }

  push(samples) {
    if (samples.length > this.buffer.length - this.length) throw new Error('fifo overflow');
    for (let i = 0; i < samples.length; i++) {
      this.buffer[this.writeIndex] = samples[i];
      this.writeIndex = (this.writeIndex + 1) % this.buffer.length;
    }
    this.length += samples.length;
  }

  /** Copies `target.length` samples out; returns false (and copies nothing) when too few are queued. */
  pull(target) {
    if (target.length > this.length) return false;
    for (let i = 0; i < target.length; i++) {
      target[i] = this.buffer[this.readIndex];
      this.readIndex = (this.readIndex + 1) % this.buffer.length;
    }
    this.length -= target.length;
    return true;
  }

  clear() {
    this.readIndex = 0;
    this.writeIndex = 0;
    this.length = 0;
  }
}

const frameLevelDb = (frame) => {
  let energy = 0;
  for (let i = 0; i < frame.length; i++) energy += frame[i] * frame[i];
  return 10 * Math.log10(energy / frame.length + 1e-12);
};

/**
 * Speech gate driven by the model's activity estimate, applied after the model.
 *
 * `activity` is 0..1 (RNNoise's voice probability, or DeepFilterNet's local SNR mapped through a
 * logistic curve). The gate opens once `openFrames` consecutive frames are above `openThreshold`
 * and the model kept the frame (its output is within `keptWithinDb` of the input, so a keystroke
 * the model removed does not count), stays open while activity is above `closeThreshold`, and
 * holds for `holdFrames` frames after. Output is delayed by `lookaheadFrames` so the gain ramp
 * finishes before the first speech frame comes out. When closed the gain is `closedGain`.
 */
class ActivityGate {
  constructor(options) {
    this.options = { ...options };
    this.queue = [];
    this.gain = options.closedGain;
    this.targetGain = options.closedGain;
    this.open = false;
    this.run = 0;
    this.hold = 0;
    this.currentActivity = 0;
  }

  configure(options) {
    Object.assign(this.options, options);
    if (!this.open) this.targetGain = this.options.closedGain;
  }

  /** Delay in frames the gate adds. */
  get delayFrames() {
    return this.options.lookaheadFrames;
  }

  /**
   * @param frame denoised model frame (not modified)
   * @param inputLevelDb level of the raw input frame
   * @param activity model speech activity 0..1
   * @returns the gated frame from `lookaheadFrames` earlier (silence at the start)
   */
  process(frame, inputLevelDb, activity) {
    const o = this.options;
    const outLevelDb = frameLevelDb(frame);
    const kept = outLevelDb > inputLevelDb - o.keptWithinDb;
    this.currentActivity = activity;
    if (activity >= o.openThreshold && kept) this.run += 1;
    else if (activity < o.closeThreshold) this.run = 0;
    if (this.run >= o.openFrames) {
      this.open = true;
      this.hold = o.holdFrames;
    } else if (this.open) {
      if (activity >= o.closeThreshold && kept) this.hold = o.holdFrames;
      else if (this.hold > 0) this.hold -= 1;
      else this.open = false;
    }
    this.targetGain = this.open ? 1 : o.closedGain;

    this.queue.push(frame.slice());
    if (this.queue.length <= o.lookaheadFrames) return new Float32Array(frame.length);
    const out = this.queue.shift();
    // Ramp linearly towards the target: opening takes the lookahead frames, closing releaseFrames.
    const span = 1 - o.closedGain;
    const rate = this.open ? span / Math.max(1, o.lookaheadFrames) : span / Math.max(1, o.releaseFrames);
    const from = this.gain;
    let to = from + Math.sign(this.targetGain - from) * rate;
    if ((this.targetGain - from) * (this.targetGain - to) <= 0) to = this.targetGain;
    for (let i = 0; i < out.length; i++) out[i] *= from + ((to - from) * i) / out.length;
    this.gain = to;
    return out;
  }
}

/** Sums processing time over windows of frames and reports the share of real time used. */
class LoadMeter {
  constructor(windowFrames, frameMs) {
    this.windowFrames = windowFrames;
    this.frameMs = frameMs;
    this.frames = 0;
    this.busyMs = 0;
    this.maxMs = 0;
  }

  /** Returns the window's load (0..1) and max frame time when the window is complete, else null. */
  record(elapsedMs) {
    this.busyMs += elapsedMs;
    this.frames += 1;
    if (elapsedMs > this.maxMs) this.maxMs = elapsedMs;
    if (this.frames < this.windowFrames) return null;
    const report = { load: this.busyMs / (this.windowFrames * this.frameMs), maxFrameMs: this.maxMs, frames: this.frames };
    this.frames = 0;
    this.busyMs = 0;
    this.maxMs = 0;
    return report;
  }
}

const nowMs = typeof performance !== 'undefined' && typeof performance.now === 'function' ? () => performance.now() : () => Date.now();
const hasHighResClock = typeof performance !== 'undefined' && typeof performance.now === 'function';

// ---- RNNoise processor: hand-written glue for the emscripten build (no JS glue file needed) ----

const RNNOISE_FRAME_WINDOW = 100;
const PCM16_SCALE = 32768;

/** Instantiates the RNNoise wasm (xiph/rnnoise built with emscripten) and wraps its C API. */
const createRnnoise = (wasmModule) => {
  let memory = null;
  const imports = {
    env: {
      __assert_fail: () => { throw new Error('rnnoise assertion failed'); },
      emscripten_resize_heap: (size) => {
        const pages = Math.ceil((size - memory.buffer.byteLength) / 65536);
        if (pages > 0) { try { memory.grow(pages); } catch { return 0; } }
        return 1;
      },
      emscripten_memcpy_big: (dest, src, n) => { new Uint8Array(memory.buffer).copyWithin(dest, src, src + n); return dest; },
      emscripten_memcpy_js: (dest, src, n) => { new Uint8Array(memory.buffer).copyWithin(dest, src, src + n); return dest; },
    },
    wasi_snapshot_preview1: {
      fd_write: (fd, iov, iovcnt, pnum) => { new Uint32Array(memory.buffer)[pnum >> 2] = 0; return 0; },
      fd_close: () => 0,
      fd_seek: () => 0,
      proc_exit: () => { throw new Error('rnnoise exited'); },
    },
  };
  const instance = new WebAssembly.Instance(wasmModule, imports);
  const ex = instance.exports;
  memory = ex.memory;
  if (typeof ex.__wasm_call_ctors === 'function') ex.__wasm_call_ctors();
  const frameSize = ex.rnnoise_get_frame_size();
  const state = ex.rnnoise_create(0);
  if (!state) throw new Error('rnnoise_create failed');
  const inPtr = ex.malloc(frameSize * 4);
  const outPtr = ex.malloc(frameSize * 4);
  return {
    frameSize,
    /** Denoises `frame` (floats in -1..1) in place and returns the voice probability. */
    process(frame) {
      const inView = new Float32Array(memory.buffer, inPtr, frameSize);
      for (let i = 0; i < frameSize; i++) inView[i] = frame[i] * PCM16_SCALE;
      const vad = ex.rnnoise_process_frame(state, outPtr, inPtr);
      const outView = new Float32Array(memory.buffer, outPtr, frameSize);
      for (let i = 0; i < frameSize; i++) frame[i] = outView[i] / PCM16_SCALE;
      return vad;
    },
    destroy() {
      ex.rnnoise_destroy(state);
      ex.free(inPtr);
      ex.free(outPtr);
    },
  };
};

/**
 * Runs RNNoise on the mono input, limits its attenuation by mixing the input back in, and gates
 * pauses from its voice probability.
 *
 * processorOptions: { wasmModule, attenLimDb, gate: ActivityGate options | null, bypassUntilReady, report }
 * Messages as for DeepFilterProcessor ('configure' takes attenLimDb, gate, enabled).
 */
class RnnoiseProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    const o = options.processorOptions || {};
    this.enabled = o.enabled !== false;
    this.bypassUntilReady = o.bypassUntilReady !== false;
    this.report = Boolean(o.report);
    this.engine = null;
    this.gate = o.gate ? new ActivityGate(o.gate) : null;
    this.setAttenLim(typeof o.attenLimDb === 'number' ? o.attenLimDb : 100);
    this.disposed = false;
    this.port.onmessage = (event) => this.onMessage(event.data || {});
    try {
      if (sampleRate !== 48000) throw new Error('RNNoise needs a 48 kHz AudioContext, got ' + sampleRate);
      this.engine = createRnnoise(o.wasmModule);
      this.frameSamples = this.engine.frameSize;
      this.frame = new Float32Array(this.frameSamples);
      this.inputFifo = new SampleFifo(this.frameSamples * 4 + 512);
      this.outputFifo = new SampleFifo(this.frameSamples * 4 + 512);
      this.loadMeter = new LoadMeter(RNNOISE_FRAME_WINDOW, (this.frameSamples / sampleRate) * 1000);
      this.port.postMessage({ type: 'ready', frameSamples: this.frameSamples, lookaheadFrames: 0, gateFrames: this.gate ? this.gate.delayFrames : 0, highRes: hasHighResClock });
    } catch (error) {
      this.fail(error);
    }
  }

  setAttenLim(db) {
    this.mixBack = db >= 100 ? 0 : Math.pow(10, -Math.abs(db) / 20);
  }

  onMessage(data) {
    if (data.type === 'dispose') {
      this.disposed = true;
      if (this.engine) { try { this.engine.destroy(); } catch { /* ignore */ } }
      this.engine = null;
      return;
    }
    if (data.type !== 'configure') return;
    if (typeof data.attenLimDb === 'number') this.setAttenLim(data.attenLimDb);
    if (typeof data.enabled === 'boolean') this.enabled = data.enabled;
    if (data.gate && this.gate) this.gate.configure(data.gate);
  }

  fail(error) {
    this.engine = null;
    this.port.postMessage({ type: 'error', message: error instanceof Error ? error.message : String(error) });
  }

  process(inputs, outputs) {
    if (this.disposed) return false;
    const input = inputs[0] && inputs[0][0];
    const output = outputs[0] && outputs[0][0];
    if (!output) return true;
    if (!input) { output.fill(0); return true; }
    if (!this.engine || !this.enabled) {
      if (this.bypassUntilReady) output.set(input.subarray(0, output.length));
      else output.fill(0);
      return true;
    }
    try {
      this.inputFifo.push(input);
      while (this.inputFifo.length >= this.frameSamples) {
        this.inputFifo.pull(this.frame);
        const started = nowMs();
        const inputLevelDb = frameLevelDb(this.frame);
        const raw = this.mixBack > 0 ? this.frame.slice() : null;
        const vad = this.engine.process(this.frame);
        if (raw) for (let i = 0; i < this.frameSamples; i++) this.frame[i] = this.frame[i] * (1 - this.mixBack) + raw[i] * this.mixBack;
        const out = this.gate ? this.gate.process(this.frame, inputLevelDb, vad) : this.frame;
        this.outputFifo.push(out);
        const elapsed = nowMs() - started;
        const load = this.loadMeter.record(elapsed);
        if (load) this.port.postMessage({ type: 'load', ...load, highRes: hasHighResClock });
        if (this.report) this.port.postMessage({ type: 'frame', vad, activity: vad, open: this.gate ? this.gate.open : true, inputLevelDb });
      }
      if (!this.outputFifo.pull(output)) output.fill(0);
    } catch (error) {
      this.fail(error);
      if (this.bypassUntilReady) output.set(input.subarray(0, output.length));
      else output.fill(0);
    }
    return true;
  }
}

registerProcessor('rnnoise-processor', RnnoiseProcessor);
